async function (triggerType, triggerData, reactorToken, item, activationName, api) {
	const target = triggerData.targets[0]
    const effect = api.findEffectOnToken(target, "bolster")

    if (!effect) {
      	ui.notifications.warn("Effect not found.");
    	return;
        }

    await effect.update({
    	"flags.lancer-automations.duration": {
      	label: "indefinite",
      	turns: null,
      	rounds: null
    	},
    	"flags.lancer-automations.-=durationEntries": null
    })
}

