async function (triggerType, triggerData, reactorToken, item, activationName, api) {
    if (!await api.consumeOncePerRound(reactorToken, "sysop_agressive_countermeasures")) {
      return;
    }
    await api.applyEffectsToTokens({
        tokens: triggerData.targets,
        effectNames: {
            name: "Agressive Countermeasures",
            icon: "systems/lancer/assets/icons/white/shield_outline.svg",
            isCustom: true
        },
        duration: {
            label: "indefinite",
            turns: null,
            rounds: null
        }
    });
}

async function (triggerType, triggerData, reactorToken, item, activationName, api)
                {
                    const chosen = await api.chooseToken(reactorToken, {
                        count: 1,
                        range: reactorToken.actor.system.sensor_range,
                        glow: 'sensor',
                        filter: (target) => !api.findEffectOnToken(target, "bolster")
                    });
                    if (!chosen || chosen.length === 0)
                        return;
                    const targets = chosen;

                    const validTargets = await api.applyEffectsToTokens({
                        tokens: targets,
                        effectNames: "bolster",
                        note: "Bolster",
                        duration: { label: 'end', turns: 1, rounds: 0 }
                    });

                    if (!validTargets || validTargets.length === 0)
                        return;

                    await api.dispatchCustomTrigger("onBolsterResolved", {
                      triggeringToken: reactorToken,
                      targets: validTargets,
                      actionName: "Bolster"
                    });

                    const weaponFx = game.modules.get("lancer-weapon-fx");
                    if (!weaponFx?.active || typeof Sequencer === 'undefined')
                        return;

                    await Sequencer.Preloader.preloadForClients([
                        "modules/lancer-weapon-fx/soundfx/TechPrepare.ogg",
                        "jb2a.zoning.inward.circle.once.bluegreen.01.01",
                    ]);

                    validTargets.forEach(target =>
                    {
                        let sequence = new Sequence()
                            .sound()
                            .file("modules/lancer-weapon-fx/soundfx/TechPrepare.ogg")
                            .volume(weaponFx.api.getEffectVolume(0.7))
                            .effect()
                            .file("modules/lancer-automations/FX/svg/Bolster.svg")
                            .xray(true)
                            .attachTo(target, { align: "bottom-left", edge: "inner", offset: { x: -0.07, y: -0.07 }, gridUnits: true })
                            .scaleIn(0.01, 500)
                            .scale(0.09)
                            .scaleOut(0.01, 900)
                            .filter("Glow", { distance: 2, color: 0x000000 })
                            .aboveInterface()
                            .duration(3000)
                            .fadeIn(400)
                            .fadeOut(800)
                            .effect()
                            .file("jb2a.zoning.inward.circle.once.bluegreen.01.01")
                            .xray(true)
                            .scaleToObject(1.5)
                            .filter("Glow", { color: 0x36c11a })
                            .playbackRate(1.3)
                            .atLocation(target)
                            .waitUntilFinished(-400);
                        sequence.play();
                    });
                }

