async function (triggerType, triggerData, reactorToken, item, activationName, api)
                {
                    if (triggerType === 'onInitCheck')
                    {
                        triggerData.flowState.injectBonus({
                            name: "Bolster",
                            type: "accuracy",
                            val: 2
                        });

                    }
                    else if (triggerType === 'onCheck')
                    {
                        await api.removeEffectsByNameFromTokens({
                            tokens: [reactorToken],
                            effectNames: ["bolster"]
                        });
                    }
                }

Agressive Countermeasures Heat Reduction.evaluate:
function (triggerType, triggerData, reactorToken, item, activationName, api) {
    const damage = triggerData.flowState.data.damage
    if (!api.findEffectOnToken(reactorToken, "Aggressive Countermeasures"))
        return false;
    if (!api.isHostile(reactorToken, triggerData.triggeringToken)) {
        return false;
    }
    if (!triggerData.hitTokens?.some(target => target?.id === reactorToken.id)) {
        return false
    }
    return damage.some(entry => entry.type?.toLowerCase() === "heat");
}

Agressive Countermeasures Heat Reduction.activationCode:
async function (triggerType, triggerData, reactorToken, item, activationName, api) {
    if (!await api.consumeOncePerRound(reactorToken, "sysop_agressive_countermeasures")) {
      return;
    }
    await api.removeEffectsByName(reactorToken.id, "Agressive Countermeasures")
    await api.addGlobalBonus(reactorToken.actor, {
        name: "Agressive Countermeasures",
        type: "immunity",
        uses: 1,
        subtype: "damage",
        damageTypes: [
            "Heat"
        ],
        consumeOnUsage: true
    }, {
        duration: "indefinite",
        durationTurns: 1,
        origin: reactorToken.id,
        consumption: {
            trigger: "onDamage",
            originId: reactorToken.id,
            role: "any"
        }
    });

}

Firewall.activationCode:
async function(triggerType, triggerData,reactorToken,item,activationName,api) {
    const FIREWALL_BONUS_ID = "firewall_difficulty_to_attacker"
	if (triggerType === 'onStatusApplied')
                    {
                        await api.addConstantBonus(reactorToken.actor, {
                            id: FIREWALL_BONUS_ID,
                            name: "Firewall",
                            type: "difficulty",
                            val: 1,
                            rollTypes: ["tech_attack"],
                            applyToTargetter: true
                        });
                    }
                    else if (triggerType === 'onStatusRemoved')
                        await api.removeConstantBonus(reactorToken.actor, bonus => [FIREWALL_BONUS_ID].includes(bonus.id));
                }
